    "article": "51",
    "article_display": "Art. 51",
    "speech_number": "Artigo 51 do Código de Defesa do Consumidor",
    "title": "Das Cláusulas Abusivas Nulas de Pleno Direito",
    "hierarchy": {
      "title_num": "Título I - Capítulo VI: Da Proteção Contratual e Cláusulas Abusivas",
      "chapter_num": "Direito de Arrependimento de 7 Dias (Art. 49), Cláusulas Nulas de Pleno Direito (Art. 51) e Contratos de Adesão (Art. 54)"
    },
    "category": "Práticas Abusivas e Cobrança",
    "isOabFocus": true,
    "source": {
      "name": "Presidência da República - Planalto",
      "url": "https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm#art51",
      "last_checked_at": "2026-08-15T00:00:00Z",
      "version": "1.0.0"
    },
    "official_text": "Art. 51. São nulas de pleno direito, entre outras, as cláusulas contratuais relativas ao fornecimento de produtos e serviços que:\nI - impossibilitem, exonerem ou atenuem a responsabilidade do fornecedor por vícios de qualquer natureza dos produtos e serviços ou impliquem renúncia ou disposição de direitos;\nII - subtraiam ao consumidor a opção de reembolso da quantia já paga;\nIV - estabeleçam obrigações consideradas iníquas, abusivas, que coloquem o consumidor em desvantagem exagerada, ou sejam incompatíveis com a boa-fé ou a eqüidade;\nVI - estabeleçam inversão do ônus da prova em prejuízo do consumidor;\nVII - determinem a utilização compulsória de arbitragem;\nXVI - possibilitem a renúncia do direito de indenizar pelo direito de arrependimento.",
    "content": [
      {
        "id": "cdc-art51-caput",
        "type": "caput",
        "text": "Art. 51. São nulas de pleno direito, entre outras, as cláusulas contratuais relativas ao fornecimento de produtos e serviços que:\nI - impossibilitem, exonerem ou atenuem a responsabilidade do fornecedor por vícios de qualquer natureza dos produtos e serviços ou impliquem renúncia ou disposição de direitos;\nII - subtraiam ao consumidor a opção de reembolso da quantia já paga;\nIV - estabeleçam obrigações consideradas iníquas, abusivas, que coloquem o consumidor em desvantagem exagerada, ou sejam incompatíveis com a boa-fé ou a eqüidade;\nVI - estabeleçam inversão do ônus da prova em prejuízo do consumidor;\nVII - determinem a utilização compulsória de arbitragem;\nXVI - possibilitem a renúncia do direito de indenizar pelo direito de arrependimento.",
        "speechText": "Art. 51. São nulas de pleno direito, entre outras, as cláusulas contratuais relativas ao fornecimento de produtos e serviços que: I - impossibilitem, exonerem ou atenuem a responsabilidade do fornecedor por vícios de qualquer natureza dos produtos e serviços ou impliquem renúncia ou disposição de direitos; II - subtraiam ao consumidor a opção de reembolso da quantia já paga; IV - estabeleçam obrigações consideradas iníquas, abusivas, que coloquem o consumidor em desvantagem exagerada, ou sejam incompatíveis com a boa-fé ou a eqüidade; VI - estabeleçam inversão do ônus da prova em prejuízo do consumidor; VII - determinem a utilização compulsória de arbitragem; XVI - possibilitem a renúncia do direito de indenizar pelo direito de arrependimento."
      }
    ],
    "professor_mode": {
      "simple_explanation": "Nulidade absoluta (de pleno direito) de cláusulas abusivas que exonerem responsabilidade, prevejam arbitragem compulsória ou gerem desvantagem exagerada ao consumidor.",
      "summary": "Cláusulas abusivas são nulas de pleno direito: proibida cláusula de não indenizar e imposição de arbitragem compulsória.",
      "practical_example": "Aplicação prática do Art. 51: aplicação cogente na defesa de direitos materiais e processuais em litígios e relações de consumo.",
      "exam_tip": "Atenção: O Art. 51 possui altíssima incidência nas provas de Direito do Consumidor da OAB e concursos da Magistratura, MP e Defensoria Pública.",
      "legal_terms": [
        "CDC",
        "Práticas Abusivas e Cobrança",
        "Direito do Consumidor",
        "Relação de Consumo"
      ],
      "speechText": "Modo Professor sobre o Artigo 51 do Código de Defesa do Consumidor: Nulidade absoluta (de pleno direito) de cláusulas abusivas que exonerem responsabilidade, prevejam arbitragem compulsória ou gerem desvantagem exagerada ao consumidor."
    }
